def solve(rows):
    out = []
    for start, end in sorted(rows):
        if out and start <= out[-1][1]: out[-1][1] = max(end, out[-1][1])
        else: out.append([start, end])
    return out

holdout-parallel.routes.py:
def solve(rows):
    out = {}
    for r in rows:
        key = r["destination"]
        choice = [r["cost"], r["hop"]]
        if key not in out or choice < out[key]: out[key] = choice
    return dict(sorted(out.items()))

holdout-parallel.tags.py:
def solve(rows):
    if not rows: return []
    shared = set(rows[0])
    for row in rows[1:]: shared.intersection_update(row)
    return sorted(shared)

