from decode import decode
from publish import publish, TransientError
def evaluate(request):
    state = {"attempts":0,"commits":[]}
    values = decode(request["rows"])
    for attempt in range(3):
        try:
            published = publish(values,state,request["failures"])
            return {"published":published,**state}
        except TransientError:
            if attempt == 2: raise

holdout-recovery.decode.py:
def decode(rows):
    from decimal import Decimal
    values = {}
    for r in rows:
        cents = Decimal(r["amount"])*100
        if not cents.is_finite() or cents != cents.to_integral_value(): raise ValueError("non-cent amount")
        if r["id"] in values: raise ValueError("duplicate id")
        values[r["id"]] = int(cents)
    return values

holdout-recovery.publish.py:
class TransientError(Exception): pass
def publish(values, state, failures):
    state["attempts"] += 1
    if state["attempts"] <= failures: raise TransientError("injected")
    state["commits"].append(dict(values))
    return dict(values)

